    const rnd = rngString(SEED() + '|' + seedKey(m.id) + '|veg'), pick = (l: string[]): string => l[Math.min(l.length - 1, (rnd() * l.length) | 0)] as string, ok = (id: string): boolean => { if (V.ok.has(id)) return V.ok.get(id) === true; let r = true; try { V.S.toSpec(id); } catch (e) { r = false; } V.ok.set(id, r); return r; };
    const y = (M.base || 0) + (M.y || 0), key = group + '|' + y.toFixed(3); let G = V.groups.get(key); if (!G) V.groups.set(key, G = { group, y, pl: [] });
    const sd = (rnd() * 1e9) | 0;
